// ==========================================================================
// Validate Checklist Update & Build Meta WhatsApp Template Notification
// ==========================================================================

const DEFAULT_CHECKLIST_URL = 'https://swift-erp-architecture-review-ddlqd6zew.vercel.app/';
const DEFAULT_BOSS_NUMBERS = ['919798637485']; // Boss Number 1
const TEMPLATE_NAME = 'erp_architecture_review_update';
const TEMPLATE_LANG = 'en_IN';

// 1. Parse incoming payload (supports both JSON and text/plain stringified JSON)
const inputItem = $input.first().json;
let raw = inputItem.body !== undefined ? inputItem.body : inputItem;

if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw.trim());
  } catch (err) {
    return [{
      json: {
        isValid: false,
        error: 'Failed to parse text/plain JSON payload: ' + err.message
      }
    }];
  }
}

if (!raw || typeof raw !== 'object') {
  return [{
    json: {
      isValid: false,
      error: 'Invalid payload: request body must be a JSON object'
    }
  }];
}

// 2. Validate essential fields (NO 42-item completion requirement!)
const itemTitle = raw.itemTitle ? String(raw.itemTitle).trim() : '';
if (!itemTitle) {
  return [{
    json: {
      isValid: false,
      error: 'Validation failed: "itemTitle" is required to identify the checklist item'
    }
  }];
}

const sectionTitle = raw.sectionTitle ? String(raw.sectionTitle).trim() : 'Architecture Review';

let checked = false;
if (typeof raw.checked === 'boolean') {
  checked = raw.checked;
} else if (raw.checked === 'true' || raw.checked === 1 || raw.checked === '1') {
  checked = true;
} else if (raw.checked === 'false' || raw.checked === 0 || raw.checked === '0') {
  checked = false;
}

const note = raw.note ? String(raw.note).trim() : '';
const updatedBy = raw.updatedBy ? String(raw.updatedBy).trim() : 'Reviewer';
const timestamp = raw.timestamp ? String(raw.timestamp).trim() : new Date().toISOString();
const checklistUrl = raw.checklistUrl || raw.pageUrl || DEFAULT_CHECKLIST_URL;
const statusText = checked ? 'Reviewed / Done' : 'Unchecked / Pending';
const displayNote = note !== '' ? note : 'None'; // Meta strictly rejects empty string "" parameters!

// 3. Format IST time
let formattedTime = timestamp;
try {
  const d = new Date(timestamp);
  formattedTime = isNaN(d.getTime())
    ? new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) + ' IST'
    : d.toLocaleString('en-IN', {
        timeZone: 'Asia/Kolkata',
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      }) + ' IST';
} catch (e) {
  formattedTime = timestamp;
}

// 4. Resolve & sanitize recipient numbers (no placeholders like BOSS_NUMBER_1)
const candidateNumbers = [];
if (raw.recipientPhoneNumber) candidateNumbers.push(raw.recipientPhoneNumber);
if (raw.recipientNumbers) {
  if (Array.isArray(raw.recipientNumbers)) candidateNumbers.push(...raw.recipientNumbers);
  else candidateNumbers.push(...String(raw.recipientNumbers).split(','));
}
if (typeof process !== 'undefined' && process.env && process.env.BOSS_WHATSAPP_NUMBERS) {
  candidateNumbers.push(...process.env.BOSS_WHATSAPP_NUMBERS.split(','));
}
if (candidateNumbers.length === 0) {
  candidateNumbers.push(...DEFAULT_BOSS_NUMBERS);
}

const validRecipients = [];
for (const num of candidateNumbers) {
  if (!num) continue;
  const str = String(num).trim();
  if (/^BOSS_NUMBER/i.test(str)) continue; // Drop placeholder
  const digits = str.replace(/\D/g, '');
  if (digits.length === 10) validRecipients.push('91' + digits);
  else if (digits.length === 12 && digits.startsWith('91')) validRecipients.push(digits);
  else if (digits.length >= 10 && digits.length <= 15) validRecipients.push(digits);
}

const recipients = Array.from(new Set(validRecipients.length > 0 ? validRecipients : DEFAULT_BOSS_NUMBERS));

// 5. Output one item per recipient
return recipients.map(phone => ({
  json: {
    isValid: true,
    recipientPhone: phone,
    sectionTitle,
    itemTitle,
    checked,
    status: statusText,
    note: displayNote,
    updatedBy,
    formattedTime,
    checklistUrl,
    timestamp,
    metaPayload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'template',
      template: {
        name: TEMPLATE_NAME,
        language: {
          code: TEMPLATE_LANG
        },
        components: [
          {
            type: 'body',
            parameters: [
              { type: 'text', text: String(sectionTitle) },
              { type: 'text', text: String(itemTitle) },
              { type: 'text', text: String(statusText) },
              { type: 'text', text: String(displayNote) },
              { type: 'text', text: String(updatedBy) },
              { type: 'text', text: String(formattedTime) },
              { type: 'text', text: String(checklistUrl) }
            ]
          }
        ]
      }
    },
    freeformPayload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: {
        preview_url: true,
        body: `*ERP Architecture Review Update*\n\n*Section:* ${sectionTitle}\n*Checklist Item:* ${itemTitle}\n*Status:* ${checked ? '✅ Reviewed / Done' : '⬜ Unchecked / Pending'}\n*Note:* ${displayNote}\n*Updated by:* ${updatedBy}\n*Time:* ${formattedTime}\n\n*Checklist:* ${checklistUrl}`
      }
    }
  }
}));

// ==========================================================================
// Evaluate Meta API Response
// ==========================================================================
const input = $input.first().json;
const prev = $('Code: Validate & Prepare Notification').first().json;

if (input.messages && input.messages[0]) {
  return [{
    json: {
      success: true,
      recipient: prev.recipientPhone,
      messageId: input.messages[0].id,
      status: 'SENT',
      itemTitle: prev.itemTitle,
      checked: prev.checked
    }
  }];
}

const err = input.error || input;
const code = err.code || 'UNKNOWN';
const message = err.message || JSON.stringify(err);

let remediation = 'Check Meta WhatsApp API credentials and configuration.';
if (code === 131047) {
  remediation = 'Customer service 24h window closed. Approved template erp_architecture_review_update is required.';
} else if (code === 100) {
  remediation = 'Invalid parameter: verify recipient phone number and template parameters.';
} else if (code === 190) {
  remediation = 'WhatsApp Access Token expired or invalid.';
}

return [{
  json: {
    success: false,
    recipient: prev.recipientPhone,
    errorCode: code,
    errorMessage: message,
    remediation,
    itemTitle: prev.itemTitle,
    checked: prev.checked
  }
}];
